INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S2-Q2$batch11$, 156, 2, 2, $batch11$Weaken$batch11$, $batch11$Body temperature can be estimated by the relative proportion of two oxygen isotopes in bone. Such estimates derived from dinosaur fossils suggest that dinosaurs had nearly the same body temperature in their limbs as in the rest of their bodies. Typically, the core body temperature of cold-blooded animals today is much higher than the body temperature in their limbs. Thus, dinosaurs were probably warm-blooded.$batch11$, $batch11$Which one of the following, if true, most seriously weakens the argument?$batch11$, $batch11$B$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Large warm-blooded animals keep their core body temperature slightly higher than the body temperature in their limbs.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$The fossilization process introduces changes to bones such that their original oxygen isotope ratios cannot be predicted.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Oxygen was more abundant in Earth’s atmosphere during the period in which the dinosaurs lived.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Small warm-blooded animals like mice tend to have more uniform body temperatures than do large warm-blooded animals like elephants.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Warm-blooded animals are more active and use more oxygen than cold-blooded animals.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Dinosaurs were probably warm-blooded.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Oxygen isotopes in dinosaur fossils suggest the limbs had nearly the same temperature as the rest of the body. Cold-blooded animals today have cores much warmer than their limbs.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The whole argument rests on the isotope readings from fossils. If those readings don't reflect the living animal, the evidence collapses.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show the fossil isotope readings are unreliable.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$A slight core-limb difference in warm-blooded animals is still consistent with dinosaurs being warm-blooded.$batch11$), ($batch11$B$batch11$, $batch11$If fossilization changes the isotope ratios unpredictably, the temperature estimates mean nothing.$batch11$), ($batch11$C$batch11$, $batch11$Oxygen in the air doesn't show the bone readings are wrong.$batch11$), ($batch11$D$batch11$, $batch11$Differences among warm-blooded animals don't affect whether dinosaurs were warm-blooded.$batch11$), ($batch11$E$batch11$, $batch11$Activity and oxygen use never connect to the isotope evidence.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S2-Q2$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
